using System;using System.IO;using System.Diagnostics;using System.Collections.Generic;using System.Linq;using System.Security.Principal;using System.Threading;using System.Web.Script.Serialization;
internal static class SettledRpmProbe {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static object Bank(LenovoOemTransport ec,bool second,int delay){ec.SelectOem(second);int before=ec.Read(0x2F,delay);var words=new List<int>();bool coherent=true;for(int n=0;n<3;n++){int h1=ec.Read(0x85,delay),lo=ec.Read(0x84,delay),h2=ec.Read(0x85,delay);coherent&=h1==h2;words.Add(lo|(h2<<8));}int after=ec.Read(0x2F,delay);bool zero=words.All(x=>x==0),spinning=words.All(x=>x>=500&&x<=6000)&&words.Max()-words.Min()<=200;bool valid=before==128&&after==128&&coherent&&(zero||spinning);return new{Before=before,After=after,Raw=words.ToArray(),HighBytesCoherent=coherent,Valid=valid,Rpm=valid?(int?)(zero?0:words.OrderBy(x=>x).ElementAt(1)):null};}
 internal static object Observe(int delay){using(var ec=new LenovoOemTransport(false)){try{var first=Bank(ec,false,delay);var second=Bank(ec,true,delay);if(ec.ModeWrites!=0)throw new IOException("Read-only invariant failed");return new{UTC=DateTime.UtcNow.ToString("o"),DelayMs=delay,Fan1=first,Fan2=second,ModeWrites=ec.ModeWrites};}finally{ec.SelectOem(false);}}}
 public static int Main(string[] a){if(a.Length!=2)return 64;string path=Path.GetFullPath(a[1]);if(a[0]=="--elevate"){try{var p=Process.Start(new ProcessStartInfo(typeof(SettledRpmProbe).Assembly.Location,"--read \""+path+"\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden});p.WaitForExit();return p.ExitCode;}catch(Exception e){File.WriteAllText(path+".launcher.json",Json.Serialize(new{Error=e.Message}));return 1;}}
 if(a[0]!="--read"||!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 77;if(File.Exists(path))return 75;var rows=new List<object>();string error=null;bool paused=false;try{LenovoOemTransport.Verify();var auto=CoolingClient.Send("set","Auto");if(!auto.Ok)throw new IOException(auto.Error);long start=CoolingPaths.Tick;while(true){var s=CoolingClient.Send("status");if(!s.Ok)throw new IOException(s.Error);if(s.Snapshot.Faulted){string f=Path.Combine(CoolingPaths.Data,"fault.json");var fault=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(f));if(!(bool)fault["AutomaticRestored"]||fault["RecoveryError"]!=null)throw new IOException("Auto non restauré ; diagnostic matériel préalable requis");}if(s.Snapshot.Actual=="Auto"&&!s.Snapshot.Pending)break;if(CoolingPaths.Tick-start>20000)throw new IOException("Auto non confirmé");Thread.Sleep(200);}var p=CoolingClient.Send("pause");if(!p.Ok)throw new IOException(p.Error);paused=true;foreach(int delay in new[]{0,1,2,5})for(int n=0;n<12;n++){using(var ec=new LenovoOemTransport(false)){try{var first=Bank(ec,false,delay);var second=Bank(ec,true,delay);if(ec.ModeWrites!=0)throw new IOException("Read-only invariant failed");rows.Add(new{UTC=DateTime.UtcNow.ToString("o"),DelayMs=delay,Sample=n,Fan1=first,Fan2=second,ModeWrites=ec.ModeWrites});}finally{ec.SelectOem(false);}}Thread.Sleep(500);}}catch(Exception e){error=e.Message;}finally{if(paused){try{var r=CoolingClient.Send("resume-acquisition");if(!r.Ok)throw new IOException(r.Error);}catch(Exception e){error=(error??"")+" ; reprise: "+e.Message;}}File.WriteAllText(path,Json.Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Success=error==null,Error=error,QualifiedForProduction=false,FanModeWrites=0,Burn=false,Rows=rows}));}return error==null?0:1;}
}
